text:
`count = var.enabled ? 1 : 0` は「フラグが true のときだけリソースを作る」ための定番イディオムで、実務コードで極めてよく見ます(監視をオプションにする、環境によってバックアップの有無を変える、など)。count が 0 ならリソースはリストとして空になるため、参照側は `try(リソース[0].output, "既定値")` のように「無いかもしれない」前提で書きます。🔴 `? 1 : 0` を見たら「このリソースはフラグでオンオフされる」と即読みできることが読解の鍵です。

```hcl
resource "aws_cloudwatch_metric_alarm" "cpu" {
  count = var.enable_monitoring ? 1 : 0   # 読解例: フラグで作成を切替
}
```

sample:
# lesson07 ch02: count によるオンオフ
variable "enable_backup" {
  default = true
}

variable "enable_debug" {
  default = false
}

resource "terraform_data" "backup" {
  count = var.enable_backup ? 1 : 0
  input = "backup-plan"
}

resource "terraform_data" "debug" {
  count = var.enable_debug ? 1 : 0
  input = "debug-agent"
}

# count = 0 のリソースは空リストになります
output "backup_count" {
  value = length(terraform_data.backup)
}

# 「無いかもしれない」ものは try で既定値に倒して参照します
output "backup_name" {
  value = try(terraform_data.backup[0].output, "(none)")
}

output "debug_name" {
  value = try(terraform_data.debug[0].output, "(none)")
}

exercise.starter:
variable "enable_logging" {
  default = true
}

variable "enable_monitoring" {
  default = false
}

# ここに resource と output を書く

exercise.answer:
variable "enable_logging" {
  default = true
}

variable "enable_monitoring" {
  default = false
}

# 「? 1 : 0」はフラグでリソースを作る/作らないを切り替える実務の定番イディオムです。
# count = 0 のときは [0] 参照がエラーになるため、try で "off" に倒して参照します。
resource "terraform_data" "logging" {
  count = var.enable_logging ? 1 : 0
  input = "logging-on"
}

resource "terraform_data" "monitoring" {
  count = var.enable_monitoring ? 1 : 0
  input = "monitoring-on"
}

output "logging" {
  value = try(terraform_data.logging[0].output, "off")
}

output "logging_count" {
  value = length(terraform_data.logging)
}

output "monitoring" {
  value = try(terraform_data.monitoring[0].output, "off")
}
